import math

def check_expression(n):
    # Calculate (n+2)!
    try:
        n_plus_2_factorial = math.factorial(n + 2)
    except OverflowError:
        # Handle potential overflow for large n, although n <= 10 here, so this is unlikely
        return None

    numerator = 3 * (n_plus_2_factorial + 1)
    denominator = 2 * n - 1

    if denominator == 0:
        return None

    # Check if the expression is an integer
    if numerator % denominator == 0:
        return numerator // denominator
    else:
        return None

results = {}
print("Testing n from 0 to 10...")
for n in range(11): # 0 to 10 inclusive
    result = check_expression(n)
    if result is not None:
        results[n] = result
    print(f"n={n}: Integer result = {result is not None}")

print("\nFinal results (n: value):", results)
